/* Aufgabenfelder sind direkt mit den gezeichneten Akteuren und Verbindungen verbunden. */
function planActorName(index){const value=state.tasks.planDiagram?.values?.[index];return value!==null&&value!==undefined?mappingTasks.planDiagram.options[value]:'Akteur '+['A','B','C'][index];}
function planEndpoint(index){return `<span class="plan-endpoint"><b aria-hidden="true">${['A','B','C'][index]}</b><span data-plan-actor="${index}">${esc(planActorName(index))}</span></span>`;}
function planInput(index){const t=mappingTasks.planDiagram;const value=state.tasks.planDiagram?.values?.[index];const text=t.options[value]??'';const checked=state.tasks.planDiagram?.checked;const correct=value===t.items[index][1];return `<select id="mapping-planDiagram-${index}" data-mapping="planDiagram" data-item="${index}" aria-describedby="mapping-hint-planDiagram-${index}" ${checked?`aria-invalid="${!correct}"`:''}><option value="">Begriff auswählen …</option>${t.options.map((option,n)=>`<option value="${n}" ${value===n?'selected':''}>${esc(option)}</option>`).join('')}</select>${index>2?`<span class="plan-selection" data-plan-selection="${index}" aria-hidden="true">${esc(text.length>32?text:'')}</span>`:''}<span id="mapping-hint-planDiagram-${index}" class="small">${checked?(correct?'Richtig zugeordnet.':'Diese Zuordnung bitte noch einmal prüfen.'):''}</span>`;}
function planActorField(index){return `<div class="plan-actor-field plan-actor-${index}"><label for="mapping-planDiagram-${index}"><span class="actor-letter">${['A','B','C'][index]}</span><span>${['Wer erstellt den Plan?','Wer stellt Güter her?','Wer arbeitet und konsumiert?'][index]}</span></label>${planInput(index)}</div>`;}
function planRoute(index,from,to){return `<div class="plan-route mapping-row"><div class="plan-route-direction" aria-hidden="true">${planEndpoint(from)}<span class="route-arrow">→</span>${Array.isArray(to)?`<span class="route-recipients">${to.map(planEndpoint).join('<span class="route-and">und</span>')}</span>`:planEndpoint(to)}</div><label for="mapping-planDiagram-${index}">${mappingTasks.planDiagram.items[index][0]}: Was wird weitergegeben?</label>${planInput(index)}</div>`;}
function planDiagramHTML(){const t=mappingTasks.planDiagram;return `<section class="original-task" aria-labelledby="title-planDiagram"><h3 id="title-planDiagram">${t.title}</h3><p>${t.intro}</p><h4 class="diagram-part-title">Schritt 1 · Wer ist beteiligt?</h4><div class="actor-diagram" role="group" aria-label="Drei Akteure der Zentralverwaltungswirtschaft"><div class="actor-top">${planActorField(0)}</div><svg class="actor-connectors" viewBox="0 0 600 76" aria-hidden="true" focusable="false"><path d="M295 4L148 66M305 4L452 66"/><path d="M148 66L158 49M148 66L169 67M452 66L431 67M452 66L442 49"/></svg><div class="actor-bottom">${planActorField(1)}${planActorField(2)}</div><p class="small actor-key">Die Buchstaben A, B und C findest du an den Verbindungen wieder.</p></div><h4 class="diagram-part-title">Schritt 2 · Was verbindet die Akteure?</h4><p class="small">Lies jede Verbindung von links nach rechts. Die Pfeilspitze zeigt, wer etwas erhält.</p><div class="plan-routes">${planRoute(3,0,[1,2])}${planRoute(4,1,0)}${planRoute(5,2,0)}${planRoute(6,2,1)}${planRoute(7,1,2)}</div><button class="secondary" data-check-mapping="planDiagram">Schaubild prüfen</button><div id="mapping-feedback-planDiagram" role="status">${state.tasks.planDiagram?.checked?mappingFeedback('planDiagram'):''}</div></section>`;}
function refreshPlanDiagram(){document.querySelectorAll('[data-plan-actor]').forEach(el=>el.textContent=planActorName(Number(el.dataset.planActor)));document.querySelectorAll('[data-plan-selection]').forEach(el=>{const text=mappingTasks.planDiagram.options[state.tasks.planDiagram?.values?.[el.dataset.planSelection]]??'';el.textContent=text.length>32?text:'';});}
